import { gsap } from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';
import Lenis from '@studio-freight/lenis';

// Register GSAP plugins
if (typeof window !== 'undefined') {
  gsap.registerPlugin(ScrollTrigger);
}

// Initialize Lenis smooth scroll
export const onClientEntry = () => {
  // Initialize Lenis smooth scroll
  const lenis = new Lenis({
    duration: 1.2,
    easing: (t) => Math.min(1, 1.001 - Math.pow(2, -10 * t)), // easeOutExpo
    orientation: 'vertical',
    gestureOrientation: 'vertical',
    smoothWheel: true,
    wheelMultiplier: 1,
    smoothTouch: false,
    touchMultiplier: 2,
    infinite: false,
  });

  // Connect Lenis with GSAP ScrollTrigger
  lenis.on('scroll', ScrollTrigger.update);

  gsap.ticker.add((time) => {
    lenis.raf(time * 1000);
  });

  gsap.ticker.lagSmoothing(0);

  // Request animation frame for Lenis
  function raf(time) {
    lenis.raf(time);
    requestAnimationFrame(raf);
  }

  requestAnimationFrame(raf);

  // Store lenis instance globally for access in components
  if (typeof window !== 'undefined') {
    window.lenis = lenis;
  }

  console.log('✨ GSAP ScrollTrigger and Lenis smooth scroll initialized');
};

// Cleanup on route change
export const onRouteUpdate = ({ location, prevLocation }) => {
  // Scroll to top on route change
  if (typeof window !== 'undefined' && window.lenis) {
    window.lenis.scrollTo(0, { immediate: true });
  }

  // Update ScrollTrigger on route change
  if (typeof window !== 'undefined') {
    ScrollTrigger.refresh();
  }
};

// Prevent scroll restoration (let Lenis handle it)
export const shouldUpdateScroll = () => {
  return false;
};
